/* By AlzRiss - Usanagi Umi AI
 *
 * Pengirim "rich message" WhatsApp: HTML di dalam chat, langsung bisa dimainkan.
 *
 * Digunakan oleh plugin game (mis. game-sonic, trading-wa). Pesan dibungkus
 * sebagai forward dari AI bot resmi supaya WhatsApp mau mem-render HTML-nya
 * inline tanpa meminta unduhan berkas.
 */

import { randomUUID } from 'crypto'

// Sertifikat & tanda tangan dari contoh publik MessageBuilder V4.7.
// Dipakai apa adanya — jangan diubah kecuali WhatsApp mengganti skemanya.
const SIG = "TklYRUwuTWVzc2FnZUJ1aWxkZXJWNC43LVZlcmlmaWNhdGlvblNpZ25hdHVyZS5NZXRhZGF0YcN55YRyad2+ZA=="
const CERT1 = ""
const CERT2 = ""

/**
 * Kirim HTML menjadi rich message yang bisa langsung dimainkan di chat.
 * @param {import('baileys').WASocket} conn
 * @param {string} chatId
 * @param {string} html  HTML mandiri (tanpa aset eksternal)
 * @param {string} judul judul kecil di atas kartu
 */
export async function kirimForwardSigned(conn, chatId, html, judul) {
    const data = Buffer.from(JSON.stringify({
        __typename: 'GenAIUnifiedResponse',
        response_id: randomUUID(),
        sections: [{
            __typename: 'GenAIUnifiedResponseSection',
            view_model: {
                __typename: 'GenAISingleLayoutViewModel',
                primitive: {
                    __typename: 'GenAIaeacdsnwHtmlPrimitive',
                    payload: html,
                    trusted_sources: []
                }
            }
        }]
    })).toString('base64')

    return conn.relayMessage(chatId, {
        messageContextInfo: {
            deviceListMetadata: {},
            deviceListMetadataVersion: 2,
            botMetadata: {
                messageDisclaimerText: "",
                botResponseId: randomUUID(),
                verificationMetadata: {
                    proofs: [{
                        version: 1,
                        useCase: 1,
                        signature: SIG,
                        certificateChain: [CERT1, CERT2]
                    }]
                }
            }
        },
        botForwardedMessage: {
            message: {
                richResponseMessage: {
                    messageType: 1,
                    submessages: [{
                        messageType: 2,
                        messageText: judul
                    }],
                    unifiedResponse: {
                        data
                    },
                    contextInfo: {
                        forwardingScore: 1,
                        isForwarded: true,
                        forwardedAiBotMessageInfo: {
                            botJid: "867051314767696@bot"
                        },
                        forwardOrigin: 4
                    }
                }
            }
        }
    }, {})
}

export default kirimForwardSigned
